import{_ as t,o as n,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"L'Ère de l'Exploration Interplans","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0078-跨位面探索纪元.md","filePath":"fr/0078-跨位面探索纪元.md"}`),a={name:"fr/0078-跨位面探索纪元.md"};function o(r,e,l,d,u,p){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="l-ere-de-l-exploration-interplans" tabindex="-1">L&#39;Ère de l&#39;Exploration Interplans <a class="header-anchor" href="#l-ere-de-l-exploration-interplans" aria-label="Permalink to &quot;L&#39;Ère de l&#39;Exploration Interplans&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>78</td></tr><tr><td>Module</td><td>Ères historiques et grands événements</td></tr><tr><td>Mots clés</td><td>exploration interplans, grandes découvertes de plans, protocole archéologique, observer d&#39;abord puis interférer, symbiose interstellaire</td></tr></tbody></table><h2 id="i-les-conditions-d-ouverture-de-l-ere-de-l-exploration-interplans" tabindex="-1">I. Les Conditions d&#39;Ouverture de l&#39;Ère de l&#39;Exploration Interplans <a class="header-anchor" href="#i-les-conditions-d-ouverture-de-l-ere-de-l-exploration-interplans" aria-label="Permalink to &quot;I. Les Conditions d&#39;Ouverture de l&#39;Ère de l&#39;Exploration Interplans&quot;">​</a></h2><p>L&#39;Ère de l&#39;Exploration Interplans est une nouvelle ère ouverte après la fondation de la République des Dix Mille Races, correspondant à l&#39;étape de transition de l&#39;« évolution de la conscience » à la « symbiose interstellaire » dans le chemin d&#39;ascension en quatre étapes. L&#39;ouverture de cette ère exigeait la maturation simultanée de trois conditions :</p><ul><li><strong>Condition technologique</strong> : la technologie des principes juridiques spatiaux atteignit le royaume du « Vide d&#39;Origine », rendant possible l&#39;ouverture stable de passages interplans ; le Miroir de Réplication et les technologies d&#39;espace isolé mûrirent, fournissant des garanties techniques pour l&#39;exploration à faible pollution.</li><li><strong>Condition institutionnelle</strong> : la République des Dix Mille Races fut fondée, et les politiques unifiées d&#39;exploration interplans ainsi que le protocole archéologique furent achevés.</li><li><strong>Condition de motivation</strong> : le travail d&#39;ascension des plans connus avança de manière ordonnée, et la civilisation avait à la fois la capacité et la volonté de s&#39;étendre vers des plans inconnus.</li></ul><p>Lorsque ces trois conditions mûrirent simultanément, la République des Dix Mille Races annonça officiellement le lancement du « Grand Plan d&#39;Exploration », et l&#39;Ère de l&#39;Exploration Interplans commença ainsi.</p><h2 id="ii-les-principes-fondamentaux-de-l-exploration-interplans" tabindex="-1">II. Les Principes Fondamentaux de l&#39;Exploration Interplans <a class="header-anchor" href="#ii-les-principes-fondamentaux-de-l-exploration-interplans" aria-label="Permalink to &quot;II. Les Principes Fondamentaux de l&#39;Exploration Interplans&quot;">​</a></h2><p>L&#39;exploration interplans suit strictement les principes fondamentaux suivants, inscrits dans la « Loi Fondamentale de l&#39;Exploration Interplans » :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Observer d&#39;abord, puis interférer de manière limitée</td><td>Les plans inconnus sont d&#39;abord soumis à une observation passive ; ce n&#39;est qu&#39;après une compréhension complète que sont menés des contacts et une interférence limités</td></tr><tr><td>Exploration à faible pollution</td><td>Adopte le schéma archéologique du Miroir de Réplication + espace isolé, ne retransmettant que le savoir, sans transporter de matière ni de vie vers l&#39;intérieur ou l&#39;extérieur</td></tr><tr><td>Protection des civilisations autochtones</td><td>Pour les plans dotés de civilisations autochtones, respecter leur droit au développement autonome ; ne pas imposer de force le système symbiotique</td></tr><tr><td>Partage des ressources</td><td>Le savoir et les ressources découverts par l&#39;exploration appartiennent à toute la civilisation ; aucune organisation ne peut monopoliser les résultats de l&#39;exploration</td></tr><tr><td>Sécurité d&#39;abord</td><td>La sécurité est toujours prioritaire pendant l&#39;exploration ; l&#39;exploration de plans à haut risque doit passer par une évaluation stricte des risques</td></tr></tbody></table><h2 id="iii-les-moyens-techniques-de-l-exploration" tabindex="-1">III. Les Moyens Techniques de l&#39;Exploration <a class="header-anchor" href="#iii-les-moyens-techniques-de-l-exploration" aria-label="Permalink to &quot;III. Les Moyens Techniques de l&#39;Exploration&quot;">​</a></h2><p>L&#39;exploration interplans utilisa de manière intégrée plusieurs technologies centrales de la civilisation symbiotique :</p><ol><li><strong>Technologie de balayage des plans</strong> : le balayage à distance des plans, basé sur des modules de perception des principes juridiques spatiaux, peut obtenir des informations de base sur un plan cible sans le contacter (structure spatiale, niveau d&#39;énergie, signes de vie, etc.).</li><li><strong>Schéma archéologique du Miroir de Réplication</strong> : effectue une réplication miroir de haute précision du plan cible, menant une recherche approfondie sur la copie miroir en espace isolé, ne retransmettant que le savoir.</li><li><strong>Sondes de communication interplans</strong> : dispositifs miniatures de communication par les lois pouvant être envoyés dans le plan cible pour une observation rapprochée, les données étant retransmises en temps réel par le réseau de communication interplans.</li><li><strong>Perception du domaine de la conscience</strong> : les cultivateurs de haut niveau perçoivent à distance le plan cible par le domaine de la conscience, obtenant des informations au niveau de la conscience que la technologie de balayage ne peut pas saisir.</li><li><strong>Déploiement à distance de l&#39;Ancre</strong> : pour les plans de niveau de sécurité plus élevé, des Ancres temporaires peuvent être déployées à distance pour établir des canaux de connexion stables.</li></ol><h2 id="iv-l-organisation-et-la-mise-en-œuvre-de-l-exploration" tabindex="-1">IV. L&#39;Organisation et la Mise en Œuvre de l&#39;Exploration <a class="header-anchor" href="#iv-l-organisation-et-la-mise-en-œuvre-de-l-exploration" aria-label="Permalink to &quot;IV. L&#39;Organisation et la Mise en Œuvre de l&#39;Exploration&quot;">​</a></h2><p>L&#39;exploration interplans est organisée et mise en œuvre de manière unifiée par le « Bureau d&#39;Exploration Interplans » de la République des Dix Mille Races, adoptant un modèle d&#39;« exploration graduée » :</p><table tabindex="0"><thead><tr><th>Niveau d&#39;exploration</th><th>Type de cible</th><th>Méthode d&#39;exploration</th><th>Configuration du personnel</th></tr></thead><tbody><tr><td>Exploration de Premier Niveau</td><td>Plans désolés sans vie</td><td>Balayage à distance + recherche par Miroir de Réplication</td><td>Équipes techniques principalement</td></tr><tr><td>Exploration de Deuxième Niveau</td><td>Plans avec vie de bas niveau</td><td>Archéologie par Miroir de Réplication + investigation limitée sur place</td><td>Équipes techniques + biologistes</td></tr><tr><td>Exploration de Troisième Niveau</td><td>Plans avec civilisations autochtones</td><td>Observer d&#39;abord puis contacter, en suivant strictement le protocole de contact</td><td>Équipe complète + diplomates + observateurs éthiques</td></tr><tr><td>Exploration de Quatrième Niveau</td><td>Plans à haut risque/inconnus</td><td>Uniquement recherche simulée en espace isolé, contact sur place interdit</td><td>Équipe de sécurité de plus haut niveau</td></tr></tbody></table><p>Chaque projet d&#39;exploration doit passer par le processus complet de « demande d&#39;exploration — évaluation des risques — examen éthique — approbation et mise en œuvre — surveillance du processus — partage des résultats ».</p><h2 id="v-les-grandes-decouvertes-de-l-ere-d-exploration" tabindex="-1">V. Les Grandes Découvertes de l&#39;Ère d&#39;Exploration <a class="header-anchor" href="#v-les-grandes-decouvertes-de-l-ere-d-exploration" aria-label="Permalink to &quot;V. Les Grandes Découvertes de l&#39;Ère d&#39;Exploration&quot;">​</a></h2><p>Après l&#39;ouverture de l&#39;Ère de l&#39;Exploration Interplans, la civilisation symbiotique réalisa une série de grandes découvertes :</p><ul><li><strong>Découverte de nouvelles races</strong> : un grand nombre de races intelligentes auparavant inconnues furent découvertes dans des plans inconnus, élargissant considérablement la généalogie des Dix Mille Races. Ces nouvelles races rejoignirent progressivement la République des Dix Mille Races après choix volontaire.</li><li><strong>Découverte de nouvelles lois</strong> : les structures de lois des différents plans diffèrent, et de nombreux nouveaux variants de lois furent découverts durant l&#39;exploration, enrichissant les fondements théoriques des Trois Cents Systèmes de Culture.</li><li><strong>Vestiges de civilisations anciennes</strong> : les vestiges de plusieurs civilisations éteintes de l&#39;Ère Pré-Ancre furent découverts, et une grande quantité de connaissances historiques précieuses fut obtenue par l&#39;archéologie du Miroir de Réplication.</li><li><strong>Civilisations symbiotiques d&#39;autres plans</strong> : sur certains plans furent découvertes des civilisations autochtones ayant développé indépendamment le concept de symbiose, formant avec la Civilisation Symbiotique de l&#39;Ancre une résonance de pensée à travers l&#39;espace.</li><li><strong>Exploration de la frontière de l&#39;univers</strong> : l&#39;exploration toucha progressivement la frontière connue de l&#39;Univers Hengyuan, approfondissant continuellement la compréhension de la structure globale de l&#39;univers.</li></ul><h2 id="vi-defis-et-reflexions-dans-l-exploration" tabindex="-1">VI. Défis et Réflexions dans l&#39;Exploration <a class="header-anchor" href="#vi-defis-et-reflexions-dans-l-exploration" aria-label="Permalink to &quot;VI. Défis et Réflexions dans l&#39;Exploration&quot;">​</a></h2><p>L&#39;exploration interplans ne fut pas sans heurts ; le processus rencontra aussi des défis :</p><ul><li><strong>Conflits culturels</strong> : des malentendus et des conflits culturels apparurent dans les contacts avec les civilisations autochtones, poussant à l&#39;amélioration continue du protocole de contact.</li><li><strong>Controverses éthiques de l&#39;exploration</strong> : des débats éthiques persistants eurent lieu sur « s&#39;il faut contacter activement les civilisations autochtones », aboutissant finalement au consensus de « pas proactif, pas d&#39;évitement, respect des choix ».</li><li><strong>Incidents de sécurité</strong> : une rupture de barrière d&#39;espace isolé se produisit lors de l&#39;exploration d&#39;un plan à haut risque ; bien que sans conséquences graves, elle poussa à une amélioration supplémentaire des normes de sécurité.</li><li><strong>Répartition des ressources</strong> : l&#39;exploration à grande échelle consomme des ressources considérables, et l&#39;équilibre entre l&#39;investissement dans l&#39;exploration et l&#39;investissement dans les besoins vitaux locaux devint le centre des débats politiques.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;Ère de l&#39;Exploration Interplans est l&#39;« ère des grandes découvertes maritimes » de la Civilisation Symbiotique de l&#39;Ancre. Elle étendit les horizons de la civilisation des plans connus à tout l&#39;univers, approfondissant la compréhension d&#39;elle-même tout en découvrant de nouveaux mondes. Le schéma d&#39;exploration à faible pollution du Miroir de Réplication + espace isolé rend l&#39;exploration de la civilisation symbiotique fondamentalement différente de toute expansion coloniale prédatrice de l&#39;histoire — ce que nous apportons n&#39;est pas la conquête et la prédation, mais le respect et le savoir ; ce que nous ramenons n&#39;est pas des ressources et des esclaves, mais la compréhension et la sagesse. Lorsque suffisamment de plans auront été explorés et que le réseau de l&#39;Ancre sera assez dense, la porte de l&#39;Ère de la Symbiose Interstellaire s&#39;ouvrira lentement.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>77-万族共和成立 (La Fondation de la République des Dix Mille Races)</li><li>79-星际共生时代展望 (Les Perspectives de l&#39;Ère de la Symbiose Interstellaire)</li><li>84-考古协议总纲 (L&#39;Aperçu Général du Protocole Archéologique)</li></ul>',26)])])}const v=t(a,[["render",o]]);export{m as __pageData,v as default};
